## 3. Result-Generation Logic (form data → recommendation)

Source: `client/src/lib/bariatricLogic.ts`

```typescript
// Bariatric Surgery Clinical Decision Logic
// Based on: 2022 ASMBS/IFSO Guidelines for Bariatric and Metabolic Surgery
// Reference: Eisenberg D, et al. Surg Obes Relat Dis. 2022;18(12):1345-1356. PMID: 36280539
// Also: 2023 American Diabetes Association Standards of Care; NICE Guidelines NG238 (2023)

export interface BariatricInput {
  // Patient demographics
  age: number;
  sex: 'male' | 'female';

  // BMI and weight history
  bmi: number;
  weightLossAttempts: number; // number of documented supervised weight loss attempts
  supervisedProgramDuration: number; // months in supervised weight loss program

  // Obesity-related comorbidities
  type2Diabetes: boolean;
  hba1c: number; // percent
  hypertension: boolean;
  sleepApnea: boolean;
  nafld: boolean; // non-alcoholic fatty liver disease / NASH
  gerd: boolean; // gastroesophageal reflux disease
  osteoarthritis: boolean;
  dyslipidemia: boolean;
  pcos: boolean; // polycystic ovary syndrome
  infertility: boolean;
  heartFailure: boolean;
  afib: boolean;
  pseudotumorCerebri: boolean;

  // Surgical risk
  priorAbdominalSurgery: boolean;
  priorBariatricSurgery: boolean;
  cirrhosis: boolean;
  portalHypertension: boolean;
  esophagealMotilityDisorder: boolean;

  // Psychological / behavioral
  psychologicalClearance: boolean;
  activeSubstanceAbuse: boolean;
  uncontrolledPsychiatricDisorder: boolean;
  nutritionConsultCompleted: boolean;

  // Procedure preference
  procedureType: 'sleeve' | 'bypass' | 'band' | 'duodenal-switch' | 'undecided';
}

export interface BariatricResult {
  candidacyScore: number; // 0–100
  recommendation: 'Strongly Recommended' | 'Recommended' | 'May Be Appropriate' | 'Not Recommended';
  bmiCategory: string;
  preferredProcedure: string;
  keyFindings: string[];
  warnings: string[];
  metabolicBenefit: string;
  references: string[];
}

export function calculateBariatricScore(input: BariatricInput): BariatricResult {
  const warnings: string[] = [];
  const keyFindings: string[] = [];
  let score = 0;

  // BMI criteria — primary driver
  let bmiCategory: string;
  if (input.bmi >= 40) {
    bmiCategory = 'Class III Obesity (BMI ≥40)';
    score += 40;
    keyFindings.push(`BMI ${input.bmi} — Class III obesity; meets primary surgical criteria per ASMBS 2022 guidelines`);
  } else if (input.bmi >= 35) {
    bmiCategory = 'Class II Obesity (BMI 35–39.9)';
    score += 30;
    keyFindings.push(`BMI ${input.bmi} — Class II obesity with comorbidities required for surgical candidacy`);
  } else if (input.bmi >= 30) {
    bmiCategory = 'Class I Obesity (BMI 30–34.9)';
    score += 15;
    keyFindings.push(`BMI ${input.bmi} — Class I obesity; surgery appropriate if metabolic comorbidities present (2022 ASMBS guideline expansion)`);
  } else {
    bmiCategory = 'BMI <30 — Below standard surgical threshold';
    warnings.push(`BMI ${input.bmi} — Below standard threshold for bariatric surgery; surgery not typically indicated`);
    score -= 20;
  }

  // Comorbidities — add to score for BMI 30–34.9; required for BMI 35–39.9
  const comorbidityCount = [
    input.type2Diabetes, input.hypertension, input.sleepApnea,
    input.nafld, input.dyslipidemia, input.heartFailure, input.afib,
    input.pseudotumorCerebri, input.osteoarthritis,
  ].filter(Boolean).length;

  if (comorbidityCount >= 2) {
    score += 20;
    keyFindings.push(`${comorbidityCount} obesity-related comorbidities — strong indication for metabolic surgery`);
  } else if (comorbidityCount === 1) {
    score += 10;
    keyFindings.push(`${comorbidityCount} obesity-related comorbidity present`);
  } else if (input.bmi < 40) {
    warnings.push('No obesity-related comorbidities documented — required for BMI <40 per most payer criteria');
  }

  // Type 2 diabetes — metabolic surgery benefit
  if (input.type2Diabetes) {
    score += 15;
    if (input.hba1c >= 8) {
      keyFindings.push(`T2DM with HbA1c ${input.hba1c}% — poorly controlled; metabolic surgery achieves remission in 50–80% of patients`);
    } else {
      keyFindings.push(`T2DM with HbA1c ${input.hba1c}% — metabolic surgery recommended per ADA Standards of Care 2023`);
    }
  }

  // Sleep apnea
  if (input.sleepApnea) {
    keyFindings.push('Obstructive sleep apnea — significant improvement/resolution expected post-surgery');
  }

  // GERD — affects procedure selection
  if (input.gerd) {
    keyFindings.push('GERD present — Roux-en-Y gastric bypass preferred over sleeve gastrectomy (sleeve may worsen GERD)');
    if (input.procedureType === 'sleeve') {
      warnings.push('Sleeve gastrectomy may worsen GERD — consider Roux-en-Y gastric bypass instead');
    }
  }

  // Supervised program
  if (input.supervisedProgramDuration >= 6) {
    score += 10;
    keyFindings.push(`${input.supervisedProgramDuration} months of supervised weight loss program completed — meets payer requirements`);
  } else if (input.supervisedProgramDuration >= 3) {
    score += 5;
    warnings.push(`Only ${input.supervisedProgramDuration} months of supervised program — most payers require 6 months`);
  } else {
    warnings.push('Supervised weight loss program not completed — required by most commercial payers (typically 6 months)');
    score -= 10;
  }

  // Psychological clearance
  if (input.psychologicalClearance) {
    score += 10;
    keyFindings.push('Psychological clearance obtained — required by all payers');
  } else {
    warnings.push('Psychological evaluation not completed — required by all payers before surgery');
    score -= 10;
  }

  // Nutrition consultation
  if (input.nutritionConsultCompleted) {
    score += 5;
    keyFindings.push('Nutrition consultation completed');
  } else {
    warnings.push('Nutrition consultation not documented — required by most payers');
  }

  // Contraindications
  if (input.activeSubstanceAbuse) {
    warnings.push('CONTRAINDICATION: Active substance abuse — surgery contraindicated until sustained sobriety (typically ≥1 year)');
    score -= 30;
  }
  if (input.uncontrolledPsychiatricDisorder) {
    warnings.push('CONTRAINDICATION: Uncontrolled psychiatric disorder — surgery contraindicated until stabilized');
    score -= 20;
  }
  if (input.cirrhosis) {
    warnings.push('Cirrhosis — significantly increased surgical risk; hepatology evaluation required; portal hypertension is relative contraindication');
    score -= 15;
  }
  if (input.priorBariatricSurgery) {
    keyFindings.push('Prior bariatric surgery — revision surgery; higher complexity and risk; specialized center required');
  }
  if (input.esophagealMotilityDisorder) {
    warnings.push('Esophageal motility disorder — sleeve gastrectomy and bypass may worsen symptoms; manometry required pre-operatively');
  }

  score = Math.max(0, Math.min(100, score));

  let recommendation: BariatricResult['recommendation'];
  let preferredProcedure: string;
  let metabolicBenefit: string;

  if (score >= 65) {
    recommendation = 'Strongly Recommended';
    preferredProcedure = input.gerd
      ? 'Roux-en-Y Gastric Bypass (RYGB) — preferred given GERD; also superior for T2DM remission'
      : input.type2Diabetes && input.bmi >= 35
      ? 'Roux-en-Y Gastric Bypass or Sleeve Gastrectomy — RYGB preferred for T2DM remission (80% vs 60%)'
      : 'Sleeve Gastrectomy (SG) or Roux-en-Y Gastric Bypass (RYGB) — discuss with patient based on anatomy, comorbidities, and preference';
    metabolicBenefit = 'Expected: 25–35% total body weight loss; T2DM remission in 50–80%; HTN remission in 60–75%; OSA resolution in 80–85%';
  } else if (score >= 45) {
    recommendation = 'Recommended';
    preferredProcedure = 'Sleeve Gastrectomy or RYGB — complete pre-operative workup including supervised program and psychological clearance';
    metabolicBenefit = 'Expected: 20–30% total body weight loss; significant improvement in metabolic comorbidities';
  } else if (score >= 25) {
    recommendation = 'May Be Appropriate';
    preferredProcedure = 'Complete remaining pre-operative requirements; bariatric surgery consultation recommended';
    metabolicBenefit = 'Metabolic benefit likely if BMI and comorbidity criteria met';
  } else {
    recommendation = 'Not Recommended';
    preferredProcedure = 'Address contraindications; optimize medical management; reassess in 6–12 months';
    metabolicBenefit = 'Insufficient criteria for surgical candidacy at this time';
  }

  return {
    candidacyScore: score,
    recommendation,
    bmiCategory,
    preferredProcedure,
    keyFindings,
    warnings,
    metabolicBenefit,
    references: [
      'Eisenberg D, et al. 2022 American Society for Metabolic and Bariatric Surgery (ASMBS) and International Federation for the Surgery of Obesity and Metabolic Disorders (IFSO) Indications for Metabolic and Bariatric Surgery. Surg Obes Relat Dis. 2022;18(12):1345-1356. PMID: 36280539',
      'American Diabetes Association. Standards of Medical Care in Diabetes—2023. Diabetes Care. 2023;46(Suppl 1):S1-S291. Section 8: Obesity and Weight Management — Metabolic surgery recommended for T2DM with BMI ≥30',
      'NICE Guideline NG238. Obesity: Identification, Assessment and Management. 2023 — Bariatric surgery for BMI ≥40 or ≥35 with comorbidity',
      'Schauer PR, et al. STAMPEDE Trial. Bariatric Surgery vs Intensive Medical Therapy for Diabetes. N Engl J Med. 2017;376(7):641-651. PMID: 28199805 — Surgery superior to medical therapy for T2DM control at 5 years',
      'Sjöström L, et al. Swedish Obese Subjects Study. Bariatric Surgery and Long-Term Cardiovascular Events. JAMA. 2012;307(1):56-65. PMID: 22215166 — Surgery reduces cardiovascular events and mortality',
    ],
  };
}
